<?php
namespace Cyberfort\AIRegister; defined( 'ABSPATH' ) || exit;
class Cache { public function key( string $endpoint, array $params = [], string $language = 'en' ): string { $fingerprint = substr( hash( 'sha256', (string) get_option( 'cfair_api_key' ) ), 0, 6 ); ksort( $params ); return 'cfair_' . get_option( 'cfair_api_version', 'v1' ) . '_' . $fingerprint . '_' . $language . '_' . sanitize_key( $endpoint ) . '_' . substr( hash( 'sha256', wp_json_encode( $params ) . '|1' ), 0, 8 ); } public function get( string $key ): array|false { $value = get_transient( $key ); return is_array( $value ) ? $value : false; } public function put( string $key, array $value ): void { set_transient( $key, $value, (int) get_option( 'cfair_cache_duration', 900 ) ); update_option( $key . '_lkg', $value, false ); } public function stale( string $key ): array|false { $value = get_option( $key . '_lkg', false ); return is_array( $value ) && ( time() - (int) ( $value['timestamp'] ?? 0 ) < (int) get_option( 'cfair_stale_retention', WEEK_IN_SECONDS ) ) ? $value : false; } public function clear(): void { global $wpdb; $wpdb->query( "DELETE FROM {$wpdb->options} WHERE option_name LIKE '_transient_cfair_%' OR option_name LIKE 'cfair_%_lkg'" ); } }
